// jobVariant is the badge of the state of a job or the outcome of a run;
// the text names it.
func jobVariant(state string) BadgeVariant {
	switch state {
	case JobSucceeded:
		return BadgeSuccess
	case JobFailed:
		return BadgeDanger
	case JobRunning:
		return BadgeInfo
	case RunLost:
		return BadgeWarning
	default:
		return BadgeDefault
	}
}

